+  it("isEmpty is true when authenticated with 0 memberships", () => {
+    const { result } = renderHook(() => useOrgWorkspaceSelection());
+    expect(result.current.isEmpty).toBe(true);
+    expect(result.current.isLoading).toBe(false);
+  });
